const body = $json.body || $json;
const sessionId = body.sessionId || `academ_${Date.now()}_${Math.random().toString(36).substr(2,8)}`;
const action = body.action || 'chat';
const mode = body.mode || 'drafting';
const discipline = body.discipline || 'general_academic';
const outputFormat = body.outputFormat || 'markdown';
const citationFormat = body.citationFormat || 'APA7';
const language = body.language || 'indonesia';

return {
  sessionId, action, mode, discipline,
  outputFormat, citationFormat, language,
  userMessage: body.message || body.query || '',
  targetSection: body.section || null,
  researchTopic: body.topic || null,
  journalCount: body.options?.journalCount || 10,
  yearFilter: body.options?.yearFilter || '2019-2024',
  runCitationValidator: body.options?.runCitationValidator !== false,
  hasUploadedData: body.hasUploadedData || false,
  timestamp: new Date().toISOString()
};

const mode = $json.mode || 'drafting';
const discipline = $json.discipline || 'general';
const language = $json.language || 'indonesia';
const citationFormat = $json.citationFormat || 'APA7';

const modePrompts = {
  drafting: `Tulis konten akademik baru yang lengkap dan terstruktur. Gunakan tools Semantic Scholar dan DuckDuckGo untuk mencari referensi. Sertakan sitasi (Nama, Tahun) pada setiap klaim faktual. Format output dalam Markdown dengan heading yang jelas.`,
  editing: `Review dan perbaiki tulisan yang diberikan user. Identifikasi: (1) kalimat yang tidak jelas, (2) inkonsistensi terminologi, (3) argumen yang lemah, (4) sitasi yang kurang/salah. Format output: MASALAH | VERSI ASLI | VERSI REVISI | ALASAN.`,
  paraphrasing: `Parafrase teks yang diberikan menggunakan bahasa akademik Indonesia yang berbeda dari aslinya. Pertahankan makna, tambahkan sitasi yang tepat. Estimasikan tingkat kemiripan dengan aslinya (tinggi/sedang/rendah).`,
  SLR: `Lakukan Systematic Literature Review. Gunakan Semantic Scholar secara intensif (cari 15+ jurnal). Buat: (1) Tabel penelitian terdahulu dengan kolom: No, Peneliti/Tahun, Judul, Metode, Variabel, Hasil Utama, Relevansi. (2) Sintesis naratif per tema. (3) Research gap.`,
  proposal: `Buat proposal penelitian lengkap dengan struktur: Bab I (Latar Belakang, Rumusan Masalah, Tujuan, Manfaat), Bab II (Tinjauan Pustaka singkat, Kerangka Teori, Hipotesis), Bab III (Rencana Metode), Daftar Pustaka sementara.`,
  abstract: `Buat abstrak akademik dalam DUA bahasa: (1) ABSTRAK INDONESIA (150-200 kata): latar belakang singkat, tujuan, metode, hasil utama, kesimpulan. (2) ABSTRACT ENGLISH (150-200 words): background, objective, method, results, conclusion. Tambahkan KATA KUNCI (3-6) dan KEYWORDS (3-6).`,
  statistics: `Interpretasikan hasil statistik yang diberikan untuk konteks penelitian akademik. Jelaskan: statistik deskriptif, uji asumsi klasik, hasil analisis utama (koefisien, signifikansi p-value), pengujian hipotesis (diterima/ditolak), dan kaitkan dengan teori dan literatur terkait. Gunakan bahasa yang mudah dipahami.`
};

const modeTemp = {
  drafting: 0.3, editing: 0.2, paraphrasing: 0.7,
  SLR: 0.3, proposal: 0.3, abstract: 0.3, statistics: 0.2
};

return {
  ...$json,
  modePrompt: modePrompts[mode] || modePrompts.drafting,
  temperature: modeTemp[mode] || 0.3,
  modeLabel: mode.toUpperCase()
};

const topic = $json.researchTopic || $json.userMessage;
const discipline = $json.discipline || 'general';
const journalCount = $json.journalCount || 10;
const yearFilter = $json.yearFilter || '2019-2024';
const hasData = $json.hasUploadedData || false;

const sections = [
  { id: 'research_phase', label: '🔍 Research Phase', mode: 'drafting',
    prompt: `Cari ${journalCount} jurnal relevan tentang: "${topic}" dari Semantic Scholar (bahasa Inggris, ${yearFilter}). Juga cari data statistik lokal via DuckDuckGo. Simpan semua referensi untuk digunakan di seluruh bab.` },
  { id: 'abstrak', label: '📄 Abstrak', mode: 'abstract',
    prompt: `Buat abstrak Indonesia & Inggris (150-200 kata) untuk penelitian: "${topic}". Gunakan referensi dari research phase.` },
  { id: 'bab1', label: '📖 BAB I — Pendahuluan', mode: 'drafting',
    prompt: `Tulis BAB I Pendahuluan lengkap untuk: "${topic}". Sertakan: 1.1 Latar Belakang (800+ kata dengan data terkini), 1.2 Rumusan Masalah, 1.3 Tujuan Penelitian, 1.4 Manfaat Penelitian.` },
  { id: 'bab2', label: '📚 BAB II — Tinjauan Pustaka', mode: 'SLR',
    prompt: `Tulis BAB II Tinjauan Pustaka untuk: "${topic}". Sertakan: 2.1 Landasan Teori (TAM, Porter, RBV jika relevan), 2.2 Penelitian Terdahulu (tabel 10-15 jurnal), 2.3 Kerangka Pemikiran, 2.4 Hipotesis.` },
  { id: 'bab3', label: '⚙️ BAB III — Metode Penelitian', mode: 'drafting',
    prompt: `Tulis BAB III Metode Penelitian untuk: "${topic}". Sertakan: jenis penelitian, lokasi & waktu, populasi & sampel (Slovin), teknik pengumpulan data, definisi operasional variabel (tabel), teknik analisis (regresi).` },
  { id: 'bab4', label: '📊 BAB IV — Hasil & Pembahasan', mode: hasData ? 'statistics' : 'drafting',
    prompt: hasData ? `Interpretasikan data yang diupload dan tulis BAB IV untuk: "${topic}".` : `Tulis template BAB IV untuk "${topic}" dengan contoh hasil hipotetis realistis. Tandai bagian yang perlu diganti dengan [DATA REAL].` },
  { id: 'bab5', label: '🏁 BAB V — Penutup', mode: 'drafting',
    prompt: `Tulis BAB V Kesimpulan & Saran berdasarkan seluruh pembahasan untuk: "${topic}". Sertakan keterbatasan penelitian & saran penelitian berikutnya.` },
  { id: 'daftar_pustaka', label: '📑 Daftar Pustaka', mode: 'drafting',
    prompt: `Buat Daftar Pustaka lengkap format APA 7th Edition dari semua referensi yang digunakan. Urutkan alfabetis.` }
];

return {
  ...$json,
  sections,
  totalSections: sections.length,
  currentIndex: 0,
  completedSections: [],
  startedAt: new Date().toISOString()
};

// Citation Validator
const content = $json.content || $json.userMessage || '';
const API_BASE = 'https://api.semanticscholar.org/graph/v1';
const API_KEY = $env.SEMANTIC_SCHOLAR_API_KEY || '';
const headers = API_KEY ? { 'x-api-key': API_KEY } : {};

// Extract APA citations: (Nama, Tahun) atau (Nama et al., Tahun)
const apaPattern = /\(([A-Z][a-zA-Z\u00C0-\u024F]+(?:(?:\s+&\s+|\s+et\s+al\.)?(?:\s*[A-Z][a-zA-Z]+)*)?),?\s*(\d{4})\)/g;
const doiPattern = /(?:https?:\/\/doi\.org\/|doi:\s*)(10\.\d{4,}\/\S+)/gi;

const citations = [];
let m;

while ((m = apaPattern.exec(content)) !== null) {
  citations.push({ type: 'APA', author: m[1].trim(), year: m[2], raw: m[0] });
}
while ((m = doiPattern.exec(content)) !== null) {
  citations.push({ type: 'DOI', doi: m[1], raw: m[0] });
}

if (citations.length === 0) {
  return { validationReport: '⚠️ Tidak ditemukan sitasi dalam format APA atau DOI pada teks yang diberikan.', summary: { total: 0, valid: 0, partial: 0, invalid: 0 }, allValid: true };
}

const results = [];
for (const cite of citations.slice(0, 20)) {
  let status = 'UNKNOWN';
  let found = null;
  let suggestion = null;
  try {
    if (cite.type === 'DOI') {
      const r = await fetch(`${API_BASE}/paper/DOI:${cite.doi}?fields=title,authors,year,journal`, { headers });
      if (r.ok) { found = await r.json(); status = 'VALID'; }
      else { status = 'INVALID'; suggestion = 'DOI tidak ditemukan. Cek kembali DOI.'; }
    } else {
      const q = encodeURIComponent(`${cite.author} ${cite.year}`);
      const r = await fetch(`${API_BASE}/paper/search?query=${q}&fields=title,authors,year,journal&limit=3`, { headers });
      if (r.ok) {
        const data = await r.json();
        const papers = data.data || [];
        const yearMatch = papers.filter(p => String(p.year) === String(cite.year));
        if (yearMatch.length > 0) { found = yearMatch[0]; status = 'VALID'; }
        else if (papers.length > 0) { found = papers[0]; status = 'PARTIAL'; suggestion = `Tahun berbeda: ditemukan ${papers[0].year}, dikutip ${cite.year}.`; }
        else { status = 'INVALID'; suggestion = 'Tidak ditemukan di Semantic Scholar.'; }
      }
    }
  } catch(e) { status = 'ERROR'; suggestion = e.message; }
  results.push({ raw: cite.raw, type: cite.type, status, foundTitle: found?.title, foundYear: found?.year, foundJournal: found?.journal?.name, suggestion });
}

const icons = { VALID:'✅', PARTIAL:'⚠️', INVALID:'❌', ERROR:'🔴', UNKNOWN:'❓' };
const report = results.map(r => {
  let line = `${icons[r.status]} ${r.raw} → ${r.status}`;
  if (r.foundTitle) line += `\n   📄 "${r.foundTitle}" (${r.foundYear}) — ${r.foundJournal || 'jurnal tidak diketahui'}`;
  if (r.suggestion) line += `\n   💬 ${r.suggestion}`;
  return line;
}).join('\n\n');

const valid = results.filter(r=>r.status==='VALID').length;
const partial = results.filter(r=>r.status==='PARTIAL').length;
const invalid = results.filter(r=>r.status==='INVALID').length;

return {
  validationReport: `📋 CITATION VALIDATION REPORT\n${'='.repeat(40)}\n${report}\n\n📊 Ringkasan: ${results.length} sitasi | ✅ ${valid} valid | ⚠️ ${partial} perlu cek | ❌ ${invalid} tidak valid`,
  summary: { total: results.length, valid, partial, invalid },
  allValid: invalid === 0
};

const query = $fromAI('query', 'Kata kunci pencarian jurnal di Google Scholar (contoh: media loose parts motorik halus anak usia dini PAUD)');
const SERPAPI_KEY = $env.SERPAPI_API_KEY || $env.GOOGLE_SCHOLAR_API_KEY || '';

if (SERPAPI_KEY) {
  try {
    const url = `https://serpapi.com/search.json?engine=google_scholar&q=${encodeURIComponent(query)}&api_key=${SERPAPI_KEY}&hl=id`;
    const r = await fetch(url);
    const data = await r.json();
    const papers = (data.organic_results || []).slice(0, 10).map((p, i) => {
      return `[${i+1}] **${p.title}**\n    Penulis & Sumber: ${p.publication_info?.summary || 'N/A'}\n    Link: ${p.link || 'N/A'}\n    Sitasi: ${p.inline_links?.cited_by?.total || 0}x\n    Snippet: ${p.snippet || ''}`;
    }).join('\n\n');
    return papers ? `Hasil Google Scholar untuk "${query}":\n\n${papers}` : `Tidak ada hasil ditemukan di Google Scholar.`;
  } catch (e) { return `Error SerpApi Google Scholar: ${e.message}`; }
}

// Fallback: Pencarian indeks jurnal terbuka dengan dukungan sitasi Google Scholar
try {
  const semUrl = `https://api.semanticscholar.org/graph/v1/paper/search?query=${encodeURIComponent(query)}&limit=8&fields=title,authors,year,journal,externalIds,abstract`;
  const r = await fetch(semUrl);
  if (r.ok) {
    const data = await r.json();
    if (data.data?.length) {
      const papers = data.data.map((p, i) => {
        const auth = p.authors?.map(a => a.name).join(', ') || 'N/A';
        const doi = p.externalIds?.DOI ? `https://doi.org/${p.externalIds.DOI}` : 'N/A';
        return `[${i+1}] **${p.title}**\n    Penulis: ${auth} (${p.year || 'N/A'})\n    Jurnal: ${p.journal?.name || 'Google Scholar Index'}\n    DOI/Link: ${doi}\n    Abstrak: ${p.abstract?.substring(0, 250) || 'N/A'}...`;
      }).join('\n\n');
      return `Hasil Jurnal Ilmiah (Google Scholar & Open Index) untuk "${query}":\n\n${papers}`;
    }
  }
} catch (e) {}
return `Pencarian Google Scholar untuk "${query}" selesai.`;

const output = $json.output || $json.text || '';
const req = $('📋 Parse & Validate Request').item.json;
const date = new Date().toLocaleDateString('id-ID', { year:'numeric', month:'long', day:'numeric' });
const header = `---
Generated by: AcademAI (Google Gemini 2.0 Flash)
Mode: ${req.mode?.toUpperCase() || 'DRAFTING'}
Session: ${req.sessionId}
Bahasa: ${req.language} | Sitasi: ${req.citationFormat}
Dibuat: ${date}
---

`;
const footer = `

---
> ⚠️ **Disclaimer AcademAI**: Dokumen ini dibantu AI. Selalu verifikasi fakta, cek sitasi, dan konsultasikan dengan pembimbing Anda sebelum digunakan.`;
return { documentMarkdown: header + output + footer, wordCount: output.split(/\s+/).length, sessionId: req.sessionId, outputFormat: req.outputFormat, mode: req.mode, timestamp: new Date().toISOString() };

const doc = $json;
return {
  success: true,
  sessionId: doc.sessionId,
  mode: doc.mode,
  document: {
    content: doc.documentMarkdown,
    wordCount: doc.wordCount,
    format: 'markdown',
    generatedAt: doc.timestamp
  },
  message: `✅ Dokumen berhasil dibuat (${doc.wordCount} kata, mode: ${doc.mode})`,
  nextSteps: [
    'Gunakan action: validate_citations untuk verifikasi sitasi',
    'Gunakan action: export dengan outputFormat: pdf untuk ekspor PDF',
    'Lanjutkan sesi dengan sessionId yang sama untuk bab berikutnya'
  ],
  meta: { model: 'gemini-2.0-flash', poweredBy: 'AcademAI v2.0' }
};

const title = $fromAI('title', 'Judul artikel/jurnal');
const authorsStr = $fromAI('authors', 'Nama penulis');
const year = $fromAI('year', 'Tahun publikasi') || '';
const journal = $fromAI('journal', 'Nama jurnal') || '';
const doi = $fromAI('doi', 'DOI artikel') || '';
const url = $fromAI('url', 'URL paper') || '';
const abstract = $fromAI('abstract', 'Abstrak') || '';

const API_KEY = $env.ZOTERO_API_KEY || '4qTwmtGuUkuMowkMV8LCJcE9';
const USER_ID = $env.ZOTERO_USER_ID || '21617488';
const COLLECTION = '6FJX4FDT'; // Skripsi S1 PAUD

const creators = (authorsStr || '').split(/[,&]/).map(a => {
  const parts = a.trim().split(' ');
  return parts.length > 1 ? { creatorType: 'author', firstName: parts.slice(0,-1).join(' '), lastName: parts[parts.length-1] } : { creatorType: 'author', name: a.trim() };
}).filter(c => c.name || c.lastName);

const item = [{
  itemType: 'journalArticle',
  title: title || 'Tanpa Judul',
  creators: creators.length ? creators : [{ creatorType: 'author', name: 'Peneliti' }],
  publicationTitle: journal,
  date: String(year),
  DOI: doi,
  url: url,
  abstractNote: abstract,
  collections: [COLLECTION],
  tags: [{ tag: 'AcademAI' }, { tag: 'Skripsi-PAUD' }]
}];

try {
  const r = await fetch(`https://api.zotero.org/users/${USER_ID}/items`, {
    method: 'POST',
    headers: { 'Zotero-API-Key': API_KEY, 'Content-Type': 'application/json' },
    body: JSON.stringify(item)
  });
  if (r.ok) return `✅ Berhasil disimpan ke Zotero (Koleksi Skripsi S1 PAUD): "${title}" (${year})`;
  return `Gagal simpan ke Zotero: HTTP ${r.status}`;
} catch (e) { return `Error Zotero: ${e.message}`; }

const url = $fromAI('url', 'URL web/jurnal yang ingin diekstrak');
const API_KEY = $env.FIRECRAWL_API_KEY || '';
if (!API_KEY) {
  try {
    const r = await fetch(url);
    const html = await r.text();
    return `Teks web (raw): ${html.substring(0, 1500)}`;
  } catch (e) { return `Gagal fetch: ${e.message}`; }
}
try {
  const r = await fetch('https://api.firecrawl.dev/v1/scrape', {
    method: 'POST',
    headers: { 'Authorization': `Bearer ${API_KEY}`, 'Content-Type': 'application/json' },
    body: JSON.stringify({ url, formats: ['markdown'] })
  });
  const data = await r.json();
  return data?.data?.markdown?.substring(0, 3000) || 'Gagal ekstrak markdown';
} catch (e) { return `Error Firecrawl: ${e.message}`; }
